            auto empty() -> decltype(ranges::empty(r_)) { return ranges::empty(r_); }
            auto empty() const -> decltype(ranges::empty(r_)) { return ranges::empty(r_); }
            auto data() -> decltype(ranges::data(r_)) { return ranges::data(r_); }
